/* ============================================================
   Moss — a gentle household plant-care companion
   Mobile-first. Warm paper, tactile print-like shadows,
   expressive (slightly lopsided) shapes, no glass, no neon.
   ============================================================ */

:root {
  --paper:        #faf4e8;
  --paper-deep:   #f2e9d8;
  --card:         #fffdf7;
  --ink:          #23332a;
  --ink-soft:     #5b6b5e;
  --ink-faint:    #8b978d;

  --moss:         #4d8256;
  --moss-deep:    #2f5b3b;
  --leaf:         #8fb862;
  --leaf-pale:    #dceacb;
  --clay:         #c2663f;
  --clay-pale:    #f6e2d5;
  --ochre:        #d99a2b;
  --mist:         #8fa9ae;

  --line:         rgba(35, 51, 42, .16);
  --line-strong:  rgba(35, 51, 42, .32);

  --blob-a: 28px 34px 26px 30px / 30px 26px 34px 28px;
  --blob-b: 34px 26px 30px 24px / 26px 32px 24px 34px;
  --blob-c: 22px 30px 20px 26px / 26px 20px 30px 22px;

  --lift: 0 1px 0 rgba(35,51,42,.10), 4px 6px 0 -2px rgba(47,91,59,.09);
  --lift-hi: 0 1px 0 rgba(35,51,42,.12), 7px 10px 0 -3px rgba(47,91,59,.13);

  --font: ui-rounded, "SF Pro Rounded", "Hiragino Maru Gothic ProN", Quicksand,
          "Segoe UI Variable", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background-color: var(--paper);
  background-image:
    radial-gradient(rgba(35,51,42,.055) 1.1px, transparent 1.5px),
    radial-gradient(rgba(194,102,63,.05) 1px, transparent 1.4px);
  background-size: 24px 24px, 24px 24px;
  background-position: 0 0, 12px 12px;
  line-height: 1.45;
  min-height: 100vh;
}

h1, h2, h3 { margin: 0; font-weight: 700; letter-spacing: -.01em; }
p { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ---------- focus ---------- */
:focus { outline: none; }
:focus-visible {
  outline: 3px solid var(--clay);
  outline-offset: 3px;
  border-radius: 12px;
}
.detail :focus-visible,
.toast :focus-visible { outline-color: var(--moss-deep); }

.skiplink {
  position: absolute; left: 12px; top: -60px; z-index: 60;
  background: var(--ink); color: var(--paper);
  padding: 10px 16px; border-radius: 999px;
  font-weight: 700; text-decoration: none;
  transition: top .18s ease;
}
.skiplink:focus-visible { top: 12px; }

/* ---------- shell ---------- */
.app {
  max-width: 1240px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

/* ---------- masthead ---------- */
.masthead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 14px;
  padding-bottom: 18px;
  border-bottom: 2px dashed var(--line);
  margin-bottom: 22px;
}

.brand { display: flex; align-items: center; gap: 12px; margin-right: auto; }

.brand__mark { width: 52px; height: 52px; display: block; flex: none; }
.brand__mark svg { width: 100%; height: 100%; overflow: visible; }
.mark-blob { fill: var(--leaf-pale); stroke: var(--moss); stroke-width: 2.5; }
.mark-leaf { fill: var(--moss); }
.mark-vein { stroke: var(--leaf-pale); stroke-width: 2.5; stroke-linecap: round; }
.brand__mark svg { animation: breathe 7s ease-in-out infinite; transform-origin: 50% 60%; }

.brand__text { display: flex; flex-direction: column; }
.brand__name {
  font-size: 1.7rem; line-height: 1; font-weight: 800;
  letter-spacing: -.03em;
}
.brand__tag { font-size: .82rem; color: var(--ink-soft); margin-top: 4px; }

.chip {
  font-size: .8rem; font-weight: 700;
  padding: 7px 14px;
  border-radius: 999px;
  background: var(--card);
  border: 1.5px solid var(--line);
  box-shadow: 0 2px 0 -1px rgba(35,51,42,.10);
  white-space: nowrap;
}
.chip--count {
  background: var(--moss); color: #fff; border-color: var(--moss-deep);
  box-shadow: 0 2px 0 var(--moss-deep);
}
.chip--count.is-clear {
  background: var(--ochre); border-color: #a9741c; box-shadow: 0 2px 0 #a9741c;
  color: #2a2008;
}
.chip--count.is-clear::before { content: "✓ "; }

/* ---------- layout ---------- */
.layout { display: block; }

.queue-head { margin-bottom: 16px; }
.queue-head__title { font-size: 1.32rem; }
.queue-head__note { color: var(--ink-soft); font-size: .9rem; margin-top: 4px; max-width: 46ch; }

/* ---------- queue groups ---------- */
.group { margin-bottom: 26px; }
.group__head {
  display: flex; align-items: baseline; gap: 8px;
  margin: 0 0 10px 2px;
}
.group__title {
  font-size: .78rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--ink-soft);
}
.group--overdue .group__title { color: var(--clay); }
.group__rule {
  flex: 1; height: 0; border-top: 2px dotted var(--line-strong);
}
.group__note { font-size: .78rem; color: var(--ink-faint); }

.queue { display: flex; flex-direction: column; gap: 12px; }

/* ---------- plant card ---------- */
.card {
  position: relative;
  background: var(--card);
  border: 1.5px solid var(--line);
  border-radius: var(--blob-a);
  box-shadow: var(--lift);
  transition: transform .18s ease, box-shadow .18s ease, opacity .25s ease;
  overflow: hidden;
}
.card:hover { transform: translate(-1px, -2px) rotate(-.35deg); box-shadow: var(--lift-hi); }

.card__open {
  display: flex; align-items: center; gap: 13px;
  width: 100%; padding: 14px 14px 12px;
  background: none; border: 0; font: inherit; color: inherit;
  text-align: left; cursor: pointer;
}

.thumb {
  flex: none; width: 62px; height: 62px;
  border-radius: var(--blob-c);
  background: var(--leaf-pale);
  display: grid; place-items: center;
  overflow: hidden;
  border: 1.5px solid rgba(47,91,59,.18);
}
.thumb svg { width: 100%; height: 100%; display: block; }

.card__text { min-width: 0; flex: 1; }
.card__name {
  display: block; font-size: 1.06rem; font-weight: 800; letter-spacing: -.015em;
}
.card__meta {
  display: block; font-size: .82rem; color: var(--ink-soft);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.card__task {
  display: inline-block; margin-top: 5px;
  font-size: .74rem; font-weight: 800; letter-spacing: .04em; text-transform: uppercase;
  color: var(--moss-deep); background: var(--leaf-pale);
  padding: 3px 9px; border-radius: 999px;
}

.due {
  flex: none;
  font-size: .74rem; font-weight: 800;
  padding: 5px 10px; border-radius: 999px;
  border: 1.5px solid var(--line-strong);
  background: var(--paper-deep); color: var(--ink-soft);
  white-space: nowrap;
}
.due--overdue {
  background: var(--clay-pale); border-color: var(--clay); color: #8a3f1f;
}

/* the priority card: taller, louder, with a clay spine */
.card--priority {
  border-color: var(--clay);
  background: linear-gradient(180deg, #fffdf7 0%, #fdf5ee 100%);
}
.card--priority .card__open { padding: 18px 16px 14px; gap: 15px; }
.card--priority .thumb { width: 84px; height: 84px; }
.card--priority .card__name { font-size: 1.34rem; }
.card--priority .card__meta { font-size: .88rem; white-space: normal; }
.card--priority::before {
  content: "";
  position: absolute; left: 0; top: 0; bottom: 0; width: 7px;
  background: repeating-linear-gradient(180deg, var(--clay) 0 10px, transparent 10px 18px);
}
.card--priority .flag {
  position: absolute; top: 0; right: 0;
  background: var(--clay); color: #fff5ea;
  font-size: .68rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  padding: 4px 12px 5px 14px;
  border-radius: 0 0 0 16px;
}

/* actions row */
.card__actions {
  display: flex; gap: 8px;
  padding: 0 14px 14px 14px;
}
.card--priority .card__actions { padding: 0 16px 16px 22px; }
.card__actions .act { flex: 1; }

.card--done { opacity: .62; }
.card--done .card__name { text-decoration: none; }
.card--done .thumb { filter: saturate(.75); }
.sprout {
  display: inline-block; width: 18px; height: 18px; margin-left: 6px;
  vertical-align: -3px;
}

/* ---------- buttons ---------- */
.act {
  font: inherit; font-size: .88rem; font-weight: 800;
  padding: 10px 14px;
  border-radius: 999px;
  border: 1.5px solid var(--line-strong);
  background: var(--card);
  color: var(--ink);
  cursor: pointer;
  box-shadow: 0 2px 0 rgba(35,51,42,.16);
  transition: transform .12s ease, box-shadow .12s ease, background .15s ease;
  touch-action: manipulation;
}
.act:hover { background: var(--paper-deep); }
.act:active { transform: translateY(2px); box-shadow: 0 0 0 rgba(0,0,0,0); }

.act--primary {
  background: var(--moss); border-color: var(--moss-deep); color: #fff;
  box-shadow: 0 2px 0 var(--moss-deep);
}
.act--primary:hover { background: #458050; }
.act--primary::before { content: "✓ "; opacity: .85; }

.act--ghost { background: transparent; box-shadow: none; border-style: dashed; }
.act--ghost:hover { background: var(--paper-deep); }

/* ---------- detail panel (mobile: bottom sheet) ---------- */
.detail {
  position: fixed; z-index: 40;
  left: 0; right: 0; bottom: 0;
  max-height: 90vh;
  background: var(--card);
  border-top: 2px solid var(--moss-deep);
  border-radius: 30px 30px 0 0;
  box-shadow: 0 -14px 30px rgba(35,51,42,.18);
  overflow-y: auto;
  overscroll-behavior: contain;
  transform: translateY(102%);
  visibility: hidden;
  transition: transform .3s cubic-bezier(.22,.9,.24,1), visibility .3s;
  padding: 8px 16px 30px;
}
.detail.is-open { transform: none; visibility: visible; }

.detail__close {
  position: sticky; top: 4px; float: right; z-index: 2;
  width: 40px; height: 40px; font-size: 1.5rem; line-height: 1;
  border-radius: 50%;
  border: 1.5px solid var(--line-strong);
  background: var(--paper-deep); color: var(--ink);
  cursor: pointer;
}
.detail__close:hover { background: var(--clay-pale); }

.detail__grip {
  width: 54px; height: 5px; border-radius: 99px;
  background: var(--line-strong);
  margin: 10px auto 4px;
}

.detail__portrait {
  margin: 6px auto 0;
  width: min(240px, 70%);
  aspect-ratio: 1 / 1;
  border-radius: 46% 54% 52% 48% / 52% 46% 54% 48%;
  background: radial-gradient(120% 120% at 30% 20%, #fffdf7 0%, var(--leaf-pale) 70%, #cfe2b8 100%);
  display: grid; place-items: center;
  border: 2px solid rgba(47,91,59,.22);
  overflow: hidden;
}
.detail__portrait svg { width: 100%; height: 100%; display: block; }

.detail__name { font-size: 1.5rem; margin-top: 14px; }
.detail__species {
  display: block; font-size: .88rem; font-weight: 600; color: var(--ink-soft);
  margin-top: 3px; letter-spacing: 0;
}
.detail__where {
  margin-top: 8px; font-size: .86rem; color: var(--ink-soft);
}
.pills { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }

.facts {
  margin: 16px 0 0;
  border-top: 2px dotted var(--line-strong);
}
.fact {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}
.fact__k {
  flex: none; width: 4.6rem;
  font-size: .72rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--ink-faint);
}
.fact__v { flex: 1; font-size: .92rem; font-weight: 600; }
.fact__aside { font-size: .78rem; color: var(--ink-faint); width: 100%; }

.meter { display: inline-flex; gap: 4px; vertical-align: 1px; }
.meter i {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--paper-deep); border: 1.5px solid var(--line-strong);
  display: block;
}
.meter i.on { background: var(--ochre); border-color: #a9741c; }

.detail__actions { display: flex; gap: 10px; margin: 18px 0 4px; }
.detail__actions .act { flex: 1; font-size: .95rem; padding: 12px 14px; }

.detail__sub {
  font-size: .78rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--ink-soft); margin: 22px 0 10px;
}
.history { position: relative; padding-left: 20px; }
.history::before {
  content: ""; position: absolute; left: 5px; top: 8px; bottom: 8px;
  width: 2px; background: repeating-linear-gradient(180deg, var(--line-strong) 0 5px, transparent 5px 10px);
}
.history li { position: relative; padding: 6px 0; font-size: .9rem; }
.history li::before {
  content: ""; position: absolute; left: -19px; top: 13px;
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--card); border: 2px solid var(--moss);
}
.history li:first-child::before { background: var(--ochre); border-color: #a9741c; }
.history .when { font-weight: 800; }
.history .sep { color: var(--ink-faint); padding: 0 5px; }

/* desktop placeholder inside detail */
.detail__empty { text-align: center; padding: 10px 0 6px; }
.detail__empty svg { width: min(300px, 82%); height: auto; display: block; margin: 0 auto; }
.detail__empty h2 { font-size: 1.3rem; margin-top: 6px; }
.detail__empty p { color: var(--ink-soft); font-size: .9rem; margin-top: 6px; max-width: 34ch; margin-inline: auto; }
.hint-keys {
  margin-top: 14px; font-size: .8rem; color: var(--ink-faint);
}
kbd {
  font: inherit; font-size: .76rem; font-weight: 800;
  border: 1.5px solid var(--line-strong); border-bottom-width: 3px;
  border-radius: 7px; padding: 1px 6px; background: var(--paper-deep);
}

/* ---------- weekly rhythm ---------- */
.rhythm-col { margin-top: 30px; }
.rhythm-card {
  background: var(--card);
  border: 1.5px solid var(--line);
  border-radius: var(--blob-b);
  box-shadow: var(--lift);
  padding: 18px 16px 16px;
}
.rhythm__title { font-size: 1.05rem; }
.rhythm__sub { font-size: .82rem; color: var(--ink-soft); margin-top: 4px; }

.rhythm {
  display: flex; align-items: flex-end; gap: 8px;
  margin: 16px 0 8px;
  min-height: 104px;
}
.bar {
  flex: 1; display: flex; flex-direction: column; justify-content: flex-end;
  align-items: center; gap: 6px;
  background: none; border: 0; padding: 0; font: inherit; cursor: default;
}
.bar__stem {
  width: 100%; max-width: 34px;
  border-radius: 999px 999px 10px 10px;
  background: linear-gradient(180deg, var(--leaf) 0%, var(--moss) 100%);
  border: 1.5px solid var(--moss-deep);
  min-height: 14px;
}
.bar__day {
  font-size: .72rem; font-weight: 800; color: var(--ink-soft);
  letter-spacing: .02em;
}
.bar.is-today .bar__stem {
  background: linear-gradient(180deg, var(--ochre) 0%, var(--clay) 100%);
  border-color: #8a3f1f;
}
.bar.is-today .bar__day { color: var(--clay); }
.bar.is-today { position: relative; }
.bar.is-today::after {
  content: ""; position: absolute; bottom: -8px; left: 50%; transform: translateX(-50%);
  width: 6px; height: 6px; border-radius: 50%; background: var(--clay);
}
.rhythm.is-peek .bar__stem { opacity: .55; }
.rhythm.is-peek .bar.is-today .bar__stem { opacity: 1; }

.tally {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  border-top: 2px dotted var(--line-strong);
  padding-top: 12px; font-size: .84rem; color: var(--ink-soft);
}
.tally__dots { display: inline-flex; gap: 5px; }
.tally__dots i {
  width: 12px; height: 12px; border-radius: 50%;
  border: 1.5px solid var(--line-strong); background: var(--paper-deep); display: block;
}
.tally__dots i.on { background: var(--moss); border-color: var(--moss-deep); }
.tally strong { color: var(--ink); }

/* ---------- all done ---------- */
.alldone {
  background: linear-gradient(180deg, #fffdf7, #f4f7e9);
  border: 2px dashed var(--moss);
  border-radius: var(--blob-b);
  padding: 22px 18px 20px;
  text-align: center;
  animation: pop .35s cubic-bezier(.2,1.2,.3,1);
}
.alldone[hidden] { display: none; }
.alldone__art svg { width: min(300px, 90%); height: auto; }
.ad-sun { fill: var(--ochre); opacity: .9; }
.ad-rays { stroke: var(--ochre); stroke-width: 3; stroke-linecap: round; }
.ad-pot { fill: var(--clay); }
.ad-rim { fill: #d4794f; }
.ad-stem { stroke: var(--moss); stroke-width: 5; stroke-linecap: round; fill: none; }
.ad-leaf { fill: var(--moss); }
.ad-leaf--r { fill: var(--leaf); }
.ad-spark { fill: var(--ochre); }
.alldone__title { font-size: 1.4rem; margin-top: 4px; }
.alldone__copy { color: var(--ink-soft); font-size: .92rem; margin-top: 8px; max-width: 40ch; margin-inline: auto; }
.alldone__actions { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin-top: 16px; }

/* ---------- toasts ---------- */
.toasts {
  position: fixed; z-index: 50;
  left: 12px; right: 12px; bottom: 12px;
  display: flex; flex-direction: column; gap: 8px; align-items: center;
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  display: flex; align-items: center; gap: 12px;
  max-width: 460px;
  background: var(--ink); color: #f6f2e6;
  padding: 11px 14px;
  border-radius: 999px;
  box-shadow: 0 8px 18px rgba(35,51,42,.28);
  font-size: .88rem; font-weight: 600;
  animation: rise .28s cubic-bezier(.2,1.1,.3,1);
}
.toast__icon { font-size: 1rem; }
.toast__undo {
  font: inherit; font-weight: 800;
  background: var(--ochre); color: #2a2008;
  border: 0; border-radius: 999px; padding: 6px 13px; cursor: pointer;
  box-shadow: 0 2px 0 #a9741c;
}
.toast__undo:hover { background: #e6ab3c; }
.toast__undo:active { transform: translateY(2px); box-shadow: none; }

/* ---------- footer ---------- */
.foot {
  margin-top: 34px; padding-top: 16px;
  border-top: 2px dashed var(--line);
  font-size: .78rem; color: var(--ink-faint);
}

/* ---------- plant svg bits ---------- */
.pot { fill: var(--clay); }
.pot-rim { fill: #d4794f; }
.soil { fill: #6a4a33; }
.lf { stroke: rgba(47,91,59,.35); stroke-width: 1.2; }
.vein { stroke: rgba(255,255,255,.55); stroke-width: 1.6; stroke-linecap: round; fill: none; }
.stem { stroke: var(--moss-deep); stroke-width: 4; stroke-linecap: round; fill: none; }
.spine { stroke: var(--ink-soft); stroke-width: 1.4; stroke-linecap: round; }
.flower { fill: var(--ochre); }

/* ---------- motion ---------- */
@keyframes breathe {
  0%, 100% { transform: rotate(-3deg) scale(1); }
  50%      { transform: rotate(3deg) scale(1.04); }
}
@keyframes rise {
  from { transform: translateY(14px); opacity: 0; }
  to   { transform: none; opacity: 1; }
}
@keyframes pop {
  from { transform: scale(.96) translateY(6px); opacity: 0; }
  to   { transform: none; opacity: 1; }
}
@keyframes sprout {
  from { transform: scale(.2) rotate(-40deg); opacity: 0; }
  60%  { transform: scale(1.15) rotate(6deg); opacity: 1; }
  to   { transform: none; opacity: 1; }
}
.sprout.pop { animation: sprout .45s cubic-bezier(.2,1.4,.4,1); }

/* ============================================================
   tablet — rhythm sits beside the queue
   ============================================================ */
@media (min-width: 720px) {
  .app { padding: 26px 24px 48px; }
  .queue { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
  .group--overdue .queue { grid-template-columns: minmax(0, 1fr); }
  .card__open { padding: 16px; }
  .rhythm-col { margin-top: 0; }
  .layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
    grid-template-areas: "queue rhythm";
    gap: 26px;
    align-items: start;
  }
  .queue-col { grid-area: queue; min-width: 0; }
  .rhythm-col { grid-area: rhythm; position: sticky; top: 18px; }
  .toasts { left: auto; right: 24px; bottom: 20px; align-items: flex-end; }
}

/* ============================================================
   desktop — three real columns, not one stretched column
   ============================================================ */
@media (min-width: 1000px) {
  .app { padding: 34px 32px 56px; }
  .layout {
    grid-template-columns: minmax(0, 1.05fr) minmax(320px, .62fr) minmax(240px, .42fr);
    grid-template-areas: "queue detail rhythm";
    gap: 28px;
  }
  .queue { grid-template-columns: minmax(0, 1fr); }
  .group--overdue .queue { grid-template-columns: minmax(0, 1fr); }

  /* the panel stops being a sheet and becomes a column */
  .detail {
    grid-area: detail;
    position: sticky; top: 18px;
    max-height: none; height: auto;
    transform: none; visibility: visible;
    border: 1.5px solid var(--line);
    border-radius: var(--blob-b);
    box-shadow: var(--lift);
    padding: 20px 20px 24px;
    overflow: visible;
  }
  .detail__close { display: none; }
  .detail__grip { display: none; }
  .detail__portrait { width: min(260px, 78%); }
  .rhythm-col { position: sticky; top: 18px; }

  .masthead { padding-bottom: 22px; }
  .brand__name { font-size: 2rem; }
}

@media (min-width: 1240px) {
  .queue { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .group--overdue .queue,
  .group--done .queue { grid-template-columns: minmax(0, 1fr); }
}

/* ============================================================
   reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
    scroll-behavior: auto !important;
  }
  .card:hover { transform: none; }
  .act:active { transform: none; }
}

@media print {
  .detail { position: static; transform: none; visibility: visible; }
  .toasts, .skiplink { display: none; }
}

/* ============================================================
   Moss — gentle household plant-care companion
   Plain ES2019+, no dependencies, no network.
   ============================================================ */
(function () {
  'use strict';

  /* ---------- data ------------------------------------------------
     PLANTS.json is the source of truth when the page is served over
     http(s). A verbatim copy lives here so the screen also works when
     opened straight from disk (where fetch() is blocked).
  ---------------------------------------------------------------- */
  var FALLBACK = {
    plants: [
      {"id":"fern","name":"Frida","species":"Boston fern","location":"Bathroom","task":"Water","due":"2 days overdue","urgency":4,"light":"Low, indirect","history":["Sep 19 · Misted","Sep 16 · Watered","Sep 12 · New frond"]},
      {"id":"pothos","name":"Orbit","species":"Golden pothos","location":"Bookshelf","task":"Rotate","due":"Today","urgency":2,"light":"Medium, indirect","history":["Sep 20 · Watered","Sep 14 · Rotated","Sep 10 · Wiped leaves"]},
      {"id":"cactus","name":"Dot","species":"Bunny ears cactus","location":"South window","task":"Check soil","due":"Today","urgency":1,"light":"Bright, direct","history":["Sep 08 · Watered","Sep 01 · New pad noted","Aug 22 · Rotated"]},
      {"id":"calathea","name":"Drama","species":"Calathea orbifolia","location":"Bedroom","task":"Mist","due":"Tomorrow","urgency":0,"light":"Medium, filtered","history":["Sep 21 · Misted","Sep 18 · Watered","Sep 15 · Brown edge noted"]}
    ],
    week: [1, 3, 2, 4, 2, 1, 3]
  };

  var DAY_INITIALS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  var DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

  var MOBILE = window.matchMedia('(max-width: 999px)');

  var state = {
    plants: [],
    week: [],
    openId: null,
    peek: 0,          // 0 = today, 1 = tomorrow (rhythm highlight)
    lastTrigger: null,
    undo: null,
    toastTimer: null
  };

  var $ = function (sel, root) { return (root || document).querySelector(sel); };

  /* ---------- tiny helpers ---------- */
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function announce(msg) { $('#live').textContent = msg; }

  function parseDue(text) {
    var s = String(text).toLowerCase();
    var m = s.match(/(\d+)\s+day(?:s)?\s+overdue/);
    if (m) return -parseInt(m[1], 10);
    if (s.indexOf('tomorrow') > -1) return 1;
    var n = s.match(/in\s+(\d+)\s+day/);
    if (n) return parseInt(n[1], 10);
    return 0;                                  // "today" and anything unparseable
  }

  function dueLabel(offset) {
    if (offset === 0) return 'Today';
    if (offset === 1) return 'Tomorrow';
    if (offset < 0) {
      var n = -offset;
      return n + ' day' + (n > 1 ? 's' : '') + ' overdue';
    }
    return 'In ' + offset + ' days';
  }

  function completeVerb(task) {
    var t = String(task).toLowerCase();
    if (t.indexOf('water') > -1) return 'Watered';
    if (t.indexOf('rotat') > -1) return 'Rotated';
    if (t.indexOf('mist') > -1) return 'Misted';
    if (t.indexOf('check') > -1) return 'Checked';
    if (t.indexOf('feed') > -1) return 'Fed';
    return 'Done';
  }

  function lightLevel(light) {
    var l = String(light).toLowerCase();
    if (l.indexOf('bright') > -1) return 5;
    if (l.indexOf('medium') > -1) return 3;
    return 2;                                   // low
  }

  function soilGuess(p) {
    if (p.done) return 'Just tended';
    if (p.offset < -1) return "Bone dry — Moss's guess";
    if (p.offset < 0) return "Dry on top — Moss's guess";
    if (p.task.toLowerCase().indexOf('water') > -1) return "Getting thirsty — Moss's guess";
    if (p.urgency >= 2) return "Still damp — Moss's guess";
    return "Comfortable — Moss's guess";
  }

  function lastWatered(p) {
    for (var i = 0; i < p.history.length; i++) {
      if (/water/i.test(p.history[i])) return p.history[i].split('·')[0].trim();
    }
    return 'a while ago';
  }

  /* ============================================================
     Illustrations — everything is generated SVG
     ============================================================ */
  function quad(p0, c, p1, t) {
    var u = 1 - t;
    return {
      x: u * u * p0.x + 2 * u * t * c.x + t * t * p1.x,
      y: u * u * p0.y + 2 * u * t * c.y + t * t * p1.y
    };
  }
  function quadAngle(p0, c, p1, t) {
    var dx = 2 * (1 - t) * (c.x - p0.x) + 2 * t * (p1.x - c.x);
    var dy = 2 * (1 - t) * (c.y - p0.y) + 2 * t * (p1.y - c.y);
    return Math.atan2(dy, dx) * 180 / Math.PI;
  }

  // A leaf rooted at (x,y) growing toward -y, rotated by `rot` degrees.
  function leaf(x, y, len, wid, rot, fill, stripes) {
    var w = wid, l = len;
    var d = 'M0 0 C ' + w + ' ' + (-l * 0.26) + ' ' + (w * 0.92) + ' ' + (-l * 0.76) +
            ' 0 ' + (-l) + ' C ' + (-w * 0.92) + ' ' + (-l * 0.76) + ' ' + (-w) + ' ' + (-l * 0.26) + ' 0 0 Z';
    var out = '<g transform="translate(' + x.toFixed(1) + ' ' + y.toFixed(1) + ') rotate(' + rot.toFixed(1) + ')">' +
      '<path class="lf" fill="' + fill + '" d="' + d + '"/>';
    if (stripes) {
      for (var i = 1; i <= stripes; i++) {
        var yy = -l * (i / (stripes + 1));
        var ww = w * (0.55 + 0.3 * Math.sin(Math.PI * i / (stripes + 1)));
        out += '<path class="vein" d="M0 ' + yy.toFixed(1) + ' Q ' + (ww * 0.5).toFixed(1) + ' ' +
               (yy - 3).toFixed(1) + ' ' + ww.toFixed(1) + ' ' + (yy + 1).toFixed(1) + '"/>';
        out += '<path class="vein" d="M0 ' + yy.toFixed(1) + ' Q ' + (-ww * 0.5).toFixed(1) + ' ' +
               (yy - 3).toFixed(1) + ' ' + (-ww).toFixed(1) + ' ' + (yy + 1).toFixed(1) + '"/>';
      }
    }
    out += '<path class="vein" d="M0 ' + (-l * 0.08).toFixed(1) + ' L0 ' + (-l * 0.9).toFixed(1) + '"/></g>';
    return out;
  }

  function pot(cx, top, w, h) {
    var x = cx - w / 2;
    return '<ellipse class="soil" cx="' + cx + '" cy="' + top + '" rx="' + (w / 2 - 3) + '" ry="4.5"/>' +
      '<path class="pot" d="M' + x + ' ' + top + ' L' + (x + w) + ' ' + top +
      ' L' + (x + w - 8) + ' ' + (top + h) +
      ' Q' + cx + ' ' + (top + h + 7) + ' ' + (x + 8) + ' ' + (top + h) + ' Z"/>' +
      '<rect class="pot-rim" x="' + (x - 4) + '" y="' + (top - 9) + '" width="' + (w + 8) + '" height="13" rx="6"/>';
  }

  function frond(p0, c, p1, size) {
    var out = '<path class="stem" d="M' + p0.x + ' ' + p0.y + ' Q' + c.x + ' ' + c.y + ' ' + p1.x + ' ' + p1.y + '"/>';
    for (var i = 1; i <= 9; i++) {
      var t = i / 10;
      var pt = quad(p0, c, p1, t);
      var a = quadAngle(p0, c, p1, t);
      var s = size * (1 - t * 0.55);
      if (s < 4) continue;
      out += leaf(pt.x, pt.y, s, s * 0.36, a + (i % 2 ? 0 : 180), i % 2 ? '#5f9159' : '#79a86a');
    }
    return out;
  }

  var PORTRAITS = {
    // Boston fern — arching fronds, fine leaflets
    fern: function () {
      var base = { x: 100, y: 148 }, out = '';
      var spread = [-62, -34, 0, 34, 62];
      var heights = [96, 118, 132, 116, 92];
      for (var i = 0; i < spread.length; i++) {
        var tip = { x: 100 + spread[i], y: 150 - heights[i] };
        var ctl = { x: 100 + spread[i] * 0.32, y: 150 - heights[i] * 0.82 };
        out += frond(base, ctl, tip, 19);
      }
      return out + pot(100, 150, 74, 38);
    },
    // Golden pothos — a trailing vine of alternating leaves
    pothos: function () {
      var p0 = { x: 100, y: 146 }, c = { x: 152, y: 108 }, p1 = { x: 138, y: 186 };
      var out = '<path class="stem" d="M' + p0.x + ' ' + p0.y + ' Q' + c.x + ' ' + c.y + ' ' + p1.x + ' ' + p1.y + '"/>';
      for (var i = 0; i <= 8; i++) {
        var t = i / 8;
        var pt = quad(p0, c, p1, t);
        var a = quadAngle(p0, c, p1, t);
        var s = 34 - t * 12;
        out += leaf(pt.x, pt.y, s, s * 0.72, a + (i % 2 ? 0 : 180), i % 2 ? '#5f9159' : '#8fb862');
      }
      out += leaf(96, 148, 44, 27, -52, '#6f9f5f');
      out += leaf(104, 148, 38, 24, 46, '#8fb862');
      return out + pot(100, 150, 74, 38);
    },
    // Bunny ears cactus — stacked pads with spines
    cactus: function () {
      var out = '';
      function pad(cx, cy, rx, ry, rot) {
        var g = '<g transform="translate(' + cx + ' ' + cy + ') rotate(' + rot + ')">' +
          '<ellipse class="lf" fill="#5f9159" rx="' + rx + '" ry="' + ry + '"/>';
        for (var i = 0; i < 10; i++) {
          var a = (i / 10) * Math.PI * 2;
          var ex = rx * Math.cos(a), ey = ry * Math.sin(a);
          var n = Math.hypot(ex / rx, ey / ry) || 1;
          g += '<path class="spine" d="M' + ex.toFixed(1) + ' ' + ey.toFixed(1) + ' L' +
               (ex / n + ex * 0.08).toFixed(1) + ' ' + (ey / n + ey * 0.08).toFixed(1) + '"/>';
        }
        return g + '</g>';
      }
      out += pad(74, 116, 16, 25, -17);
      out += pad(126, 120, 15, 23, 15);
      out += pad(100, 152, 23, 31, 0);
      out += '<circle class="flower" cx="74" cy="90" r="6"/><circle class="flower" cx="126" cy="96" r="5"/>';
      return out + pot(100, 168, 66, 30);
    },
    // Calathea orbifolia — big striped round leaves
    calathea: function () {
      var out = '';
      out += '<path class="stem" d="M100 152 C 96 132 90 118 84 108"/>';
      out += '<path class="stem" d="M100 152 C 106 134 112 122 118 112"/>';
      out += '<path class="stem" d="M100 152 C 100 140 101 132 100 124"/>';
      out += leaf(84, 110, 62, 44, -14, '#4d8256', 5);
      out += leaf(118, 113, 54, 38, 15, '#79a86a', 4);
      out += leaf(100, 126, 30, 20, 2, '#9dc07c', 3);
      return out + pot(100, 152, 76, 36);
    }
  };

  function portrait(id) {
    var fn = PORTRAITS[id] || PORTRAITS.fern;
    return '<svg viewBox="0 0 200 200" role="img" aria-hidden="true" focusable="false">' + fn() + '</svg>';
  }

  var SPROUT = '<svg class="sprout" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
    '<path d="M4 14c0-5.5 4-9 8-9 0 5.5-3.2 9-8 9Z" fill="#4d8256"/>' +
    '<path d="M20 14c0-5.5-4-9-8-9 0 5.5 3.2 9 8 9Z" fill="#8fb862"/>' +
    '<path d="M12 22V11" stroke="#2f5b3b" stroke-width="2.6" stroke-linecap="round"/></svg>';

  /* ============================================================
     Rendering
     ============================================================ */
  function openPlants() { return state.plants.filter(function (p) { return !p.done; }); }

  function groups() {
    var open = openPlants();
    var bySoonest = function (a, b) { return a.offset - b.offset; };
    var byUrgency = function (a, b) { return b.urgency - a.urgency; };
    return [
      { key: 'overdue', title: 'Needs you now', note: 'past due',
        items: open.filter(function (p) { return p.offset < 0; }).sort(function (a, b) {
          return a.offset - b.offset || b.urgency - a.urgency; }) },
      { key: 'today', title: 'Today', note: 'due today', items: open.filter(function (p) { return p.offset === 0; }).sort(byUrgency) },
      { key: 'soon', title: 'Up next', note: 'not yet', items: open.filter(function (p) { return p.offset > 0; }).sort(bySoonest) },
      { key: 'done', title: 'Tended today', note: 'all caught up',
        items: state.plants.filter(function (p) { return p.done; }) }
    ].filter(function (g) { return g.items.length; });
  }

  function cardHTML(p) {
    var overdue = p.offset < 0 && !p.done;
    var cls = 'card' + (overdue ? ' card--priority' : '') + (p.done ? ' card--done' : '');
    var verb = completeVerb(p.task);
    var openBtn =
      '<button class="card__open" type="button" data-open="' + esc(p.id) + '"' +
      ' aria-expanded="' + (state.openId === p.id ? 'true' : 'false') + '"' +
      ' aria-controls="detail">' +
        '<span class="thumb" aria-hidden="true">' + portrait(p.id) + '</span>' +
        '<span class="card__text">' +
          '<span class="card__name">' + esc(p.name) + (p.done ? SPROUT : '') + '</span>' +
          '<span class="card__meta">' + esc(p.species) + ' · ' + esc(p.location) + '</span>' +
          '<span class="card__task">' + esc(p.task) + '</span>' +
        '</span>' +
        '<span class="due' + (overdue ? ' due--overdue' : '') + '">' + esc(dueLabel(p.offset)) + '</span>' +
      '</button>';
    var actions = p.done
      ? '<div class="card__actions"><button class="act act--ghost" type="button" data-act="undo-done" data-id="' + esc(p.id) + '">' +
        'Undo · ' + esc(verb) + '</button></div>'
      : '<div class="card__actions">' +
        '<button class="act act--primary" type="button" data-act="complete" data-id="' + esc(p.id) + '">' +
          esc(verb) + '</button>' +
        '<button class="act" type="button" data-act="snooze" data-id="' + esc(p.id) + '">Snooze</button>' +
      '</div>';
    return '<li class="' + cls + '" data-card="' + esc(p.id) + '">' +
      (overdue ? '<span class="flag">first</span>' : '') +
      openBtn + actions + '</li>';
  }

  function renderQueue() {
    var host = $('#queueGroups');
    var gs = groups();
    host.innerHTML = gs.map(function (g) {
      return '<section class="group group--' + g.key + '">' +
        '<div class="group__head"><h3 class="group__title">' + g.title + '</h3>' +
        '<span class="group__rule"></span>' +
        '<span class="group__note">' + g.items.length + '</span></div>' +
        '<ul class="queue">' + g.items.map(cardHTML).join('') + '</ul>' +
      '</section>';
    }).join('');
  }

  function meter(n, max) {
    var out = '<span class="meter" aria-hidden="true">';
    for (var i = 1; i <= max; i++) out += '<i class="' + (i <= n ? 'on' : '') + '"></i>';
    return out + '</span>';
  }

  function emptyDetail() {
    return '<div class="detail__empty">' +
      '<svg viewBox="0 0 240 170" role="img" aria-hidden="true" focusable="false">' +
        '<rect class="ad-rim" x="18" y="140" width="204" height="10" rx="5"/>' +
        '<path class="pot" d="M42 150h44l-5 20h-34Z"/>' +
        '<path class="pot" d="M150 150h44l-5 20h-34Z"/>' +
        leaf(64, 148, 46, 20, -12, '#5f9159') +
        leaf(66, 148, 34, 15, 26, '#8fb862') +
        leaf(172, 148, 40, 30, 8, '#4d8256', 3) +
        leaf(170, 148, 28, 20, -30, '#9dc07c', 2) +
        '<circle class="flower" cx="212" cy="34" r="15"/>' +
        '<path class="ad-rays" style="stroke:#d99a2b;stroke-width:3;stroke-linecap:round;fill:none" d="M212 8v8M186 34h8M238 34h8M194 16l6 6M230 16l-6 6"/>' +
      '</svg>' +
      '<h2 id="detailTitle">Pick someone</h2>' +
      '<p>Tap a plant to see its light, its watering rhythm, and a short history of what you noticed.</p>' +
      '<p class="hint-keys"><kbd>↑</kbd><kbd>↓</kbd> to move · <kbd>Enter</kbd> to open · <kbd>Esc</kbd> to close</p>' +
    '</div>';
  }

  function renderDetail() {
    var body = $('#detailBody');
    var p = state.plants.filter(function (x) { return x.id === state.openId; })[0];
    if (!p) { body.innerHTML = emptyDetail(); return; }

    var verb = completeVerb(p.task);
    var overdue = p.offset < 0 && !p.done;
    var light = lightLevel(p.light);

    body.innerHTML =
      '<div class="detail__grip" aria-hidden="true"></div>' +
      '<div class="detail__portrait">' + portrait(p.id) + '</div>' +
      '<h2 class="detail__name" id="detailTitle">' + esc(p.name) +
        '<span class="detail__species">' + esc(p.species) + '</span></h2>' +
      '<p class="detail__where">' + esc(p.location) + ' · ' + esc(p.light) + ' light</p>' +
      '<div class="pills">' +
        '<span class="card__task">' + esc(p.task) + '</span>' +
        '<span class="due' + (overdue ? ' due--overdue' : '') + '">' +
          (p.done ? 'Tended today' : esc(dueLabel(p.offset))) + '</span>' +
      '</div>' +
      '<ul class="facts">' +
        '<li class="fact"><span class="fact__k">Light</span><span class="fact__v">' + esc(p.light) +
          ' ' + meter(light, 5) + '</span>' +
          '<span class="fact__aside">' + (light >= 5 ? 'Direct sun is fine — this one drinks fast.'
            : light >= 3 ? 'Happy a metre or two from a window.'
            : 'Keep it out of harsh sun.') + '</span></li>' +
        '<li class="fact"><span class="fact__k">Water</span><span class="fact__v">Last watered ' + esc(lastWatered(p)) + '</span>' +
          '<span class="fact__aside">' + esc(soilGuess(p)) + '</span></li>' +
        '<li class="fact"><span class="fact__k">Notes</span><span class="fact__v">' +
          p.history.length + ' logged' + (p.done ? ' · tended just now' : '') + '</span></li>' +
      '</ul>' +
      '<div class="detail__actions">' +
        (p.done
          ? '<button class="act act--ghost" type="button" data-act="undo-done" data-id="' + esc(p.id) + '">Undo · ' + esc(verb) + '</button>'
          : '<button class="act act--primary" type="button" data-act="complete" data-id="' + esc(p.id) + '">' + esc(verb) + '</button>' +
            '<button class="act" type="button" data-act="snooze" data-id="' + esc(p.id) + '">Snooze</button>') +
      '</div>' +
      '<h3 class="detail__sub">Observation history</h3>' +
      '<ol class="history">' + p.history.map(function (h) {
        var bits = String(h).split('·');
        return '<li><span class="when">' + esc((bits[0] || '').trim()) + '</span>' +
          (bits[1] ? '<span class="sep">·</span>' + esc(bits[1].trim()) : '') + '</li>';
      }).join('') + '</ol>';
  }

  function renderRhythm() {
    var todayIdx = (new Date().getDay() + 6) % 7;
    var focusIdx = (todayIdx + state.peek) % 7;
    var host = $('#rhythm');
    var bars = state.week.map(function (v, i) {
      var h = 16 + v * 21;
      var cls = 'bar' + (i === focusIdx ? ' is-today' : '');
      return '<div class="' + cls + '" title="' + DAY_NAMES[i] + ': ' + v + ' care moment' + (v === 1 ? '' : 's') + '">' +
        '<span class="bar__stem" style="height:' + h + 'px"></span>' +
        '<span class="bar__day">' + DAY_INITIALS[i] + '<span class="sr-only">' + DAY_NAMES[i] + '</span></span>' +
      '</div>';
    }).join('');
    host.innerHTML = bars;
    host.className = 'rhythm' + (state.peek ? ' is-peek' : '');
    host.setAttribute('role', 'img');
    host.setAttribute('aria-label', 'Weekly care rhythm: ' + state.week.map(function (v, i) {
      return DAY_NAMES[i] + ' ' + v;
    }).join(', ') + '. ' + DAY_NAMES[focusIdx] + ' is highlighted.');

    var sum = state.week.reduce(function (a, b) { return a + b; }, 0);
    var busiest = state.week.indexOf(Math.max.apply(null, state.week));
    $('#rhythmSub').textContent = state.peek
      ? 'Tomorrow looks like ' + state.week[focusIdx] + ' moment' + (state.week[focusIdx] === 1 ? '' : 's') + '.'
      : sum + ' moments this week · ' + DAY_NAMES[busiest] + ' is the busiest.';

    var total = state.plants.length;
    var done = state.plants.filter(function (p) { return p.done; }).length;
    var dots = '';
    for (var i = 0; i < total; i++) dots += '<i class="' + (i < done ? 'on' : '') + '"></i>';
    $('#tally').innerHTML = '<span class="tally__dots" aria-hidden="true">' + dots + '</span>' +
      '<span><strong>' + done + ' of ' + total + '</strong> tended today</span>';
  }

  function renderMeta() {
    var open = openPlants().length;
    var overdue = openPlants().filter(function (p) { return p.offset < 0; }).length;
    var chip = $('#countChip');
    if (open === 0) {
      chip.textContent = 'All clear';
      chip.classList.add('is-clear');
    } else {
      chip.textContent = open + ' to tend';
      chip.classList.remove('is-clear');
    }
    $('#queueNote').textContent = overdue
      ? overdue + ' past due. Everything else can wait its turn.'
      : open
        ? 'Nothing is late. Take them in any order you like.'
        : 'Nothing left today — the shelf is quiet.';

    var allDone = open === 0;
    $('#alldone').hidden = !allDone;
    $('#alldoneUndo').hidden = !state.undo;
    $('#alldonePeek').textContent = state.peek ? 'Back to today' : 'Peek at tomorrow';
  }

  function render() {
    renderQueue();
    renderDetail();
    renderRhythm();
    renderMeta();
    syncSheet();
  }

  /* ============================================================
     Open / close the detail panel
     ============================================================ */
  function syncSheet() {
    var d = $('#detail');
    d.classList.toggle('is-open', !!state.openId);
    // On mobile the panel is a modal-ish sheet; on desktop it is always visible.
    if (MOBILE.matches) d.setAttribute('aria-hidden', state.openId ? 'false' : 'true');
    else d.removeAttribute('aria-hidden');
  }

  function open(id, trigger) {
    state.openId = id;
    state.lastTrigger = trigger || null;
    renderQueue();
    renderDetail();
    syncSheet();
    if (MOBILE.matches) {
      var close = $('#detailClose');
      if (close) close.focus();
    } else {
      $('#detail').focus({ preventScroll: true });
    }
    var p = state.plants.filter(function (x) { return x.id === id; })[0];
    announce(p.name + ' opened. ' + p.task + ', ' + dueLabel(p.offset) + '.');
  }

  function close() {
    if (!state.openId) return;
    var trigger = state.lastTrigger;
    state.openId = null;
    renderQueue();
    renderDetail();
    syncSheet();
    if (trigger && document.contains(trigger)) trigger.focus();
    announce('Plant detail closed.');
  }

  /* ============================================================
     Actions: complete / snooze / undo
     ============================================================ */
  function findPlant(id) {
    return state.plants.filter(function (p) { return p.id === id; })[0];
  }

  function toast(text, undoLabel, onUndo) {
    var host = $('#toasts');
    host.innerHTML = '';
    var el = document.createElement('div');
    el.className = 'toast';
    el.innerHTML = '<span class="toast__icon" aria-hidden="true">✿</span>' +
      '<span class="toast__msg">' + esc(text) + '</span>';
    if (onUndo) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'toast__undo';
      btn.textContent = undoLabel;
      btn.addEventListener('click', function () {
        clearTimeout(state.toastTimer);
        host.innerHTML = '';
        onUndo();
      });
      el.appendChild(btn);
      state.undo = { label: undoLabel, run: onUndo };
    } else {
      state.undo = null;
    }
    host.appendChild(el);
    clearTimeout(state.toastTimer);
    state.toastTimer = setTimeout(function () {
      host.innerHTML = '';
      state.undo = null;
      if (!openPlants().length) $('#alldoneUndo').hidden = true;
    }, 7000);
  }

  function complete(id) {
    var p = findPlant(id);
    if (!p || p.done) return;
    var verb = completeVerb(p.task);
    p.done = true;
    p.history.unshift('Today · ' + verb);
    render();
    var sprout = document.querySelector('[data-card="' + id + '"] .sprout');
    if (sprout) sprout.classList.add('pop');
    toast(p.name + ' ' + verb.toLowerCase() + '.', 'Undo', function () {
      p.done = false;
      p.history.shift();
      render();
      announce(p.name + ' restored to ' + dueLabel(p.offset) + '.');
    });
    announce(p.name + ' marked ' + verb.toLowerCase() + '. Undo is available for a few seconds.');
  }

  function snooze(id) {
    var p = findPlant(id);
    if (!p || p.done) return;
    var from = p.offset;
    p.offset = p.offset >= 0 ? p.offset + 1 : Math.min(p.offset + 1, 0);
    render();
    toast(p.name + ' snoozed to ' + dueLabel(p.offset) + '.', 'Undo', function () {
      p.offset = from;
      render();
      announce(p.name + ' is due ' + dueLabel(p.offset) + ' again.');
    });
    announce(p.name + ' snoozed until ' + dueLabel(p.offset) + '.');
  }

  function undoDone(id) {
    var p = findPlant(id);
    if (!p || !p.done) return;
    p.done = false;
    p.history = p.history.filter(function (h) { return !/^Today ·/.test(h); });
    render();
    announce(p.name + ' is due ' + dueLabel(p.offset) + ' again.');
  }

  /* ============================================================
     Wiring
     ============================================================ */
  function onClick(e) {
    var actBtn = e.target.closest('[data-act]');
    if (actBtn) {
      var id = actBtn.getAttribute('data-id');
      var kind = actBtn.getAttribute('data-act');
      if (kind === 'complete') complete(id);
      else if (kind === 'snooze') snooze(id);
      else if (kind === 'undo-done') undoDone(id);
      return;
    }
    var openBtn = e.target.closest('[data-open]');
    if (openBtn) {
      var pid = openBtn.getAttribute('data-open');
      if (state.openId === pid) close();
      else open(pid, openBtn);
    }
  }

  function onKeydown(e) {
    if (e.key === 'Escape') {
      if (state.openId) { e.preventDefault(); close(); }
      return;
    }
    // move through the queue with arrows or j/k
    var host = $('#queueGroups');
    if (!host.contains(e.target) || e.altKey || e.ctrlKey || e.metaKey) return;
    var down = e.key === 'ArrowDown' || e.key === 'j';
    var up = e.key === 'ArrowUp' || e.key === 'k';
    if (!down && !up) return;
    var btns = Array.prototype.slice.call(host.querySelectorAll('[data-open]'));
    var i = btns.indexOf(e.target);
    if (i < 0) return;
    e.preventDefault();
    var next = btns[(i + (down ? 1 : -1) + btns.length) % btns.length];
    next.focus();
  }

  // Keep Tab inside the sheet while it is a mobile overlay.
  function trapTab(e) {
    if (e.key !== 'Tab' || !MOBILE.matches || !state.openId) return;
    var panel = $('#detail');
    var items = Array.prototype.slice.call(
      panel.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')
    ).filter(function (el) { return el.offsetParent !== null; });
    if (!items.length) return;
    var first = items[0], last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }

  function boot(data) {
    state.week = data.week && data.week.length ? data.week : [1, 3, 2, 4, 2, 1, 3];
    state.plants = data.plants.map(function (p) {
      return {
        id: p.id, name: p.name, species: p.species, location: p.location,
        task: p.task, due: p.due, urgency: p.urgency || 0, light: p.light,
        history: (p.history || []).slice(),
        offset: parseDue(p.due), done: false
      };
    });

    $('#dateChip').textContent = new Date().toLocaleDateString(undefined, {
      weekday: 'short', day: 'numeric', month: 'short'
    });

    document.addEventListener('click', onClick);
    document.addEventListener('keydown', onKeydown);
    document.addEventListener('keydown', trapTab);
    $('#detailClose').addEventListener('click', close);
    $('#alldoneUndo').addEventListener('click', function () {
      if (state.undo) { clearTimeout(state.toastTimer); $('#toasts').innerHTML = ''; state.undo.run(); }
    });
    $('#alldonePeek').addEventListener('click', function () {
      state.peek = state.peek ? 0 : 1;
      renderRhythm();
      renderMeta();
      announce(state.peek ? 'Showing tomorrow in the weekly rhythm.' : 'Showing today in the weekly rhythm.');
    });
    MOBILE.addEventListener('change', syncSheet);

    render();
  }

  function load() {
    if (location.protocol === 'file:') { boot(FALLBACK); return; }
    fetch('PLANTS.json', { cache: 'no-store' })
      .then(function (r) { if (!r.ok) throw new Error('no json'); return r.json(); })
      .then(function (d) { boot(d && d.plants ? d : FALLBACK); })
      .catch(function () { boot(FALLBACK); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', load);
  else load();
})();

