input.content:
// throwaway smoke harness: runs app.js against a tiny fake DOM
const fs = require('fs');
const vm = require('vm');

function El(sel) {
  return {
    sel, innerHTML: '', textContent: '', hidden: false, className: '',
    attrs: {}, children: [], offsetParent: {},
    classList: {
      _s: new Set(),
      add(c) { this._s.add(c); }, remove(c) { this._s.delete(c); },
      toggle(c, on) { on ? this._s.add(c) : this._s.delete(c); },
      contains(c) { return this._s.has(c); }
    },
    setAttribute(k, v) { this.attrs[k] = v; },
    getAttribute(k) { return this.attrs[k]; },
    removeAttribute(k) { delete this.attrs[k]; },
    addEventListener() {},
    focus() { global.__focused = this.sel; },
    appendChild(c) { this.children.push(c); },
    contains() { return false; },
    querySelector(s) { return null; },
    querySelectorAll() { return []; }
  };
}

const cache = {};
const document = {
  readyState: 'complete',
  _els: cache,
  querySelector(sel) { if (!cache[sel]) cache[sel] = El(sel); return cache[sel]; },
  createElement(t) { return El(t); },
  addEventListener() {},
  contains() { return false; }
};
const listeners = {};
document.addEventListener = (t, fn) => { (listeners[t] = listeners[t] || []).push(fn); };

const sandbox = {
  document,
  window: { matchMedia: () => ({ matches: true, addEventListener() {} }) },
  location: { protocol: 'file:' },
  setTimeout, clearTimeout, console, Date, Math, Array, Object, JSON, String, Number, isNaN, parseInt, parseFloat, RegExp, Error
};
sandbox.globalThis = sandbox;
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(__dirname + '/app.js', 'utf8'), sandbox, { filename: 'app.js' });

const g = (s) => cache[s];
const q = g('#queueGroups').innerHTML;
const d = g('#detailBody').innerHTML;
const r = g('#rhythm').innerHTML;

const checks = [
  ['queue renders 4 cards', (q.match(/data-card=/g) || []).length === 4],
  ['overdue group first', q.indexOf('Needs you now') < q.indexOf('>Today<')],
  ['Frida flagged priority', /card--priority/.test(q) && /pick me/.test(q)],
  ['due pills', /2 days overdue/.test(q) && /Tomorrow/.test(q)],
  ['actions present', /data-act="complete"/.test(q) && /data-act="snooze"/.test(q)],
  ['verbs derived', /Watered/.test(q) && /Rotated/.test(q) && /Misted/.test(q) && /Checked/.test(q)],
  ['rhythm 7 bars', (r.match(/class="bar/g) || []).length + (r.match(/bar is-today/g) || []).length === 7],
  ['rhythm aria label', /Weekly care rhythm/.test(g('#rhythm').getAttribute('aria-label'))],
  ['tally', /0 of 4/.test(g('#tally').innerHTML)],
  ['count chip', g('#countChip').textContent === '4 to tend'],
  ['all-done hidden at start', g('#alldone').hidden === true],
  ['portrait svg in card', /viewBox="0 0 200 200"/.test(q)],
  ['empty detail initially', /Pick someone/.test(d)]
];

// --- simulate: complete every plant via the click handler
const click = listeners.click[0];
function fakeClick(attrs) {
  const target = {
    closest(sel) {
      const key = sel.replace(/[\[\]"]/g, '');
      return attrs[key] ? { getAttribute: (k) => attrs[k] } : null;
    }
  };
  click({ target });
}
['fern', 'pothos', 'cactus', 'calathea'].forEach((id) => {
  fakeClick({ 'data-act': 'complete', 'data-id': id });
});
const q2 = g('#queueGroups').innerHTML;
checks.push(['all four completed', (q2.match(/card--done/g) || []).length === 4]);
checks.push(['all-done shown', g('#alldone').hidden === false]);
checks.push(['count chip clear', g('#countChip').textContent === 'All clear']);
checks.push(['tally 4 of 4', /4 of 4/.test(g('#tally').innerHTML)]);
checks.push(['toast rendered', g('#toasts').children.length === 1]);
checks.push(['undo button wired', g('#alldoneUndo').hidden === false]);
checks.push(['announced', /marked watered/.test(g('#live').textContent)]);

// --- undo the last one
fakeClick({ 'data-act': 'undo-done', 'data-id': 'calathea' });
const q3 = g('#queueGroups').innerHTML;
checks.push(['undo restores card', (q3.match(/card--done/g) || []).length === 3]);
checks.push(['restored to Up next', /Up next/.test(q3)]);

// --- snooze
fakeClick({ 'data-act': 'snooze', 'data-id': 'calathea' });
checks.push(['snooze pushes to In 2 days', /In 2 days/.test(g('#queueGroups').innerHTML)]);

// --- open a plant
fakeClick({ 'data-open': 'fern' });
const d2 = g('#detailBody').innerHTML;
checks.push(['detail shows plant', /Frida/.test(d2) && /Boston fern/.test(d2)]);
checks.push(['detail has light meter', /class="meter"/.test(d2) && /Low, indirect/.test(d2)]);
checks.push(['detail has water + history', /Last watered Sep 16/.test(d2) && /New frond/.test(d2)]);
checks.push(['detail actions', /data-act="undo-done"/.test(d2)]);

// --- escape closes
listeners.keydown[0]({ key: 'Escape', preventDefault() {} });
checks.push(['escape closes detail', /Pick someone/.test(g('#detailBody').innerHTML)]);

let bad = 0;
checks.forEach(([name, ok]) => { if (!ok) bad++; console.log((ok ? 'PASS ' : 'FAIL ') + name); });
console.log(bad ? '\n' + bad + ' FAILED' : '\nall ' + checks.length + ' checks passed');
process.exit(bad ? 1 : 0);

